(x, y, t) => {
  const wells = [
    [160+Math.sin(t*0.4)*120, 100+Math.cos(t*0.3)*60, 3.5],
    [320+Math.cos(t*0.35)*100, 150+Math.sin(t*0.45)*70, 2.8],
    [240+Math.sin(t*0.25+2)*160, 120+Math.cos(t*0.4+1)*100, 4.0],
    [100+Math.cos(t*0.5+1)*80, 200+Math.sin(t*0.35+3)*50, 2.2],
    [380+Math.sin(t*0.3+4)*70, 50+Math.cos(t*0.6+2)*60, 3.0],
    [200+Math.cos(t*0.2+5)*100, 220+Math.sin(t*0.3)*60, 2.5],
    [300+Math.sin(t*0.55+3)*90, 30+Math.cos(t*0.25)*80, 1.8]
  ];
  let gx = 0, gy = 0, potential = 0;
  for (const [wX, wY, mass] of wells) {
    const dx = x - wX, dy = y - wY;
    const d2 = dx*dx + dy*dy + 120;
    const d = Math.sqrt(d2);
    const force = mass / d2;
    gx += dx * force * 750;
    gy += dy * force * 750;
    potential -= mass / d;
  }
  const sx = x + gx, sy = y + gy;
  let activator = 0, inhibitor = 0;
  for (const [wX, wY, mass] of wells) {
    const d = Math.sqrt((sx-wX)**2 + (sy-wY)**2);
    const f1 = 0.06 + mass * 0.005, f2 = f1 * 0.62;
    activator += Math.sin(d*f1 - t*1.8*mass*0.4) * mass * 0.3;
    inhibitor += Math.sin(d*f2 + t*1.2*mass*0.4 + 2.1) * mass * 0.25;
  }
  activator /= 7; inhibitor /= 7;
  const kinetic = Math.sqrt(gx*gx + gy*gy) * 0.004;
  const energyPhase = Math.sin(potential*0.8 + t*0.6) * Math.tanh(kinetic*3);
  const bg = (Math.sin(sx*0.035+sy*0.022+t*0.9)+Math.sin(sx*0.028-sy*0.038+t*1.3))/2+Math.sin((sx+sy)*0.14+t*2.8)*0.25+Math.sin((sx-sy)*0.11-t*2.2)*0.2;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.06-ang*4-t*2)+Math.sin(dist*0.045+ang*5-t*1.5))*0.35;
  const fine=(Math.sin(sx*0.22+t*3.5)*Math.sin(sy*0.19-t*2.8)+Math.sin((sx*0.15+sy*0.12)+t*4)*0.3)*0.15;
  const reaction=Math.tanh((activator-inhibitor*0.62+bg*0.25+spiral+energyPhase*0.45+fine)*3.8);
  const cell=Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t*1.2)*0.6)*1.8)*0.2;
  const v=(reaction*0.8+cell*0.2)*0.5+0.5;
  const pal=[[2,2,15],[5,10,60],[10,40,120],[0,180,200],[0,255,140],[255,255,50],[255,100,30],[255,20,80],[180,10,120],[60,5,80],[2,2,15]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+kinetic*0.35;
  const edge=Math.abs(reaction)>0.6?1.25+kinetic*0.6:1.0;
  const neon=Math.abs(reaction)>0.82?1.45:1.0;
  const vig=1.0-Math.sqrt((x-240)**2+(y-120)**2)*0.001;
  const g=lum*edge*neon*Math.max(0.4,vig);
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*g)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*g)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*g)|0
  ];
}
